export const DEFAULTS=Object.freeze({difficulty:'standard',motion:'system',contrast:false,largeText:false,quality:'auto',touchScale:1,showHints:true,bindings:{}});
export const difficulties={story:{label:'História',enemyDamage:.65,enemyHealth:.8,enemySpeed:.9,cadence:1.3,attackers:1,reaction:.34},standard:{label:'Padrão',enemyDamage:1,enemyHealth:1,enemySpeed:1,cadence:1,attackers:2,reaction:.22},arcade:{label:'Arcade',enemyDamage:1.2,enemyHealth:1.18,enemySpeed:1.06,cadence:.85,attackers:2,reaction:.14}};
export const canonicalKeys=['KeyW','KeyA','KeyS','KeyD','Space','ShiftLeft','KeyF','KeyG','KeyH','KeyR','KeyT','ArrowUp','ArrowLeft','ArrowDown','ArrowRight','KeyO','KeyP','KeyJ','KeyK','KeyL','KeyU','KeyI'];
export function validatePreferences(value={}){const v=value&&typeof value==='object'?value:{};const bindings={};const used=new Set();for(const code of canonicalKeys){const key=v.bindings?.[code];if(typeof key==='string'&&/^(Key[A-Z]|Digit[0-9]|Arrow(Up|Down|Left|Right)|Space|Shift(Left|Right)|Control(Left|Right)|Alt(Left|Right)|Numpad[0-9])$/.test(key)&&!used.has(key)){bindings[code]=key;used.add(key)}}return {difficulty:difficulties[v.difficulty]?v.difficulty:'standard',motion:['system','reduced','full'].includes(v.motion)?v.motion:'system',contrast:v.contrast===true,largeText:v.largeText===true,quality:['auto','low','high'].includes(v.quality)?v.quality:'auto',touchScale:[1,1.2,1.4].includes(v.touchScale)?v.touchScale:1,showHints:v.showHints!==false,bindings}}
export function readPreferences(storage){try{return validatePreferences(JSON.parse(storage?.getItem('brasa-settings-v1')||'{}'))}catch{return validatePreferences()}}
export const preferences=readPreferences(globalThis.localStorage);
export function updatePreferences(patch,storage=globalThis.localStorage){const next=validatePreferences({...preferences,...patch});Object.assign(preferences,next);try{storage?.setItem('brasa-settings-v1',JSON.stringify(next))}catch{}globalThis.window?.dispatchEvent(new Event('brasa:settings'));return preferences}
export const reducedMotion=()=>preferences.motion==='reduced'||preferences.motion==='system'&&!!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
export function canonicalCode(event){if(event.brasaCanonical)return event.code;const mapped=Object.entries(preferences.bindings).find(([,key])=>key===event.code);if(mapped)return mapped[0];if(Object.hasOwn(preferences.bindings,event.code)&&preferences.bindings[event.code]!==event.code)return '';return event.code}
export const difficulty=id=>difficulties[id]||difficulties.standard;
